let searchTimeout;
watch(searchTerm, () => {
  clearTimeout(searchTimeout);
  searchTimeout = setTimeout(() => {
    page.value = 1;
    loadLeads();
  }, 500);
});

watch(() => props.branchId, () => {
  page.value = 1;
  loadLeads();
});

